import{_ as e,r as n,o,c,e as s,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"部件 - October CMS - 3.x","titleTemplate":false,"description":"在网站的任何地方重用 HTML 代码块。","frontmatter":{"subtitle":"在网站的任何地方重用 HTML 代码块。"},"headers":[{"level":2,"title":"渲染部件","slug":"渲染部件","link":"#渲染部件","children":[]},{"level":2,"title":"向部件传递变量","slug":"向部件传递变量","link":"#向部件传递变量","children":[{"level":3,"title":"变量作用域","slug":"变量作用域","link":"#变量作用域","children":[]},{"level":3,"title":"将标记作为变量传递","slug":"将标记作为变量传递","link":"#将标记作为变量传递","children":[]}]},{"level":2,"title":"动态部件","slug":"动态部件","link":"#动态部件","children":[{"level":3,"title":"部件执行生命周期","slug":"部件执行生命周期","link":"#部件执行生命周期","children":[]},{"level":3,"title":"在部件中调用 AJAX 处理程序","slug":"在部件中调用-ajax-处理程序","link":"#在部件中调用-ajax-处理程序","children":[{"level":4,"title":"另请参阅","slug":"另请参阅","link":"#另请参阅","children":[]}]}]}],"relativePath":"3.x/zh-cn/cms/themes/partials.md","filePath":"3.x/zh-cn/cms/themes/partials.md"}'),u={name:"3.x/zh-cn/cms/themes/partials.md"};function g(r,a,k,d,m,h){const t=n("pre-heading"),p=n("post-heading");return o(),c("div",null,[s(t),a[0]||(a[0]=l("h1",null,"部件",-1)),s(p),a[1]||(a[1]=i(`<p>部件是强大的元素，可以在不同的页面或布局中重复使用 HTML，例如，在不同<a href="./layouts.html">页面布局</a>中使用的页脚。部件也是使用 <a href="./../ajax/update-partials.html">AJAX 动态更新页面内容</a>的强大工具。</p><p>部件模板文件位于主题中的 <strong>partials</strong> 目录中。部件文件应具有 <strong>htm</strong> 扩展名。以下是最简单的部件示例。</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>This is a partial<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>配置部分对于部件是可选的，可以包含在后端用户界面中显示的可选 <strong>description</strong> 参数。此示例显示了一个定义了描述的部件。</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">description</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Demo partial</span>&quot;</span>
</code></pre></div><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>This is a partial<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>部件配置部分还可以包含组件定义。<a href="./components.html">组件文章</a>更详细地解释了组件。</p><h2 id="渲染部件"><a href="#渲染部件" class="header-anchor">#</a> 渲染部件</h2><div class="custom-block aside"><p>请记住，如果您引用子目录中的部件，则应指定子目录名称。</p></div><p><code>{% partial &quot;partial-name&quot; %}</code> Twig 标签用于渲染部件。该标签有一个必需参数 - 不带扩展名的部件文件名。<code>{% partial %}</code> 标签可以在页面、布局或另一个部件中使用。以下是引用部件的页面示例。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>sidebar<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>sidebar-contacts<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="向部件传递变量"><a href="#向部件传递变量" class="header-anchor">#</a> 向部件传递变量</h2><p>您经常需要从外部代码向部件传递变量。这使得部件更加有用。例如，您可以有一个渲染博客文章列表的部件。如果您可以将文章集合传递给部件，则同一个部件可以在博客归档页面、博客分类页面等上使用。您可以通过在 <code>{% partial %}</code> 标签中的部件名称后指定变量来向部件传递变量。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>sidebar<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>blog-posts<span class="token punctuation">&quot;</span></span> posts<span class="token operator">=</span>posts <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>您还可以提供新变量供部件使用。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>sidebar<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>sidebar-contacts<span class="token punctuation">&quot;</span></span> city<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>Vancouver<span class="token punctuation">&quot;</span></span> country<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>Canada<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>在部件内部，变量可以像任何其他标记变量一样访问。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Country: <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> country <span class="token delimiter punctuation">}}</span></span>, city: <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> city <span class="token delimiter punctuation">}}</span></span>.<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h3 id="变量作用域"><a href="#变量作用域" class="header-anchor">#</a> 变量作用域</h3><p>部件内容将可以访问当前上下文中的变量和提供的额外变量。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>mypartial<span class="token punctuation">&quot;</span></span> foo<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>bar<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>在以下示例中，<code>foo</code> 变量将在 <code>mypartial</code> 部件模板中可用。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> foo <span class="token operator">=</span> <span class="token string"><span class="token punctuation">&quot;</span>bar<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>mypartial<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>您可以通过附加 <code>only</code> 关键字来禁用对上下文的访问。在此示例中，只有 <code>foo</code> 变量可以访问。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>mypartial<span class="token punctuation">&quot;</span></span> foo<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>bar<span class="token punctuation">&quot;</span></span> only <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>在下一个示例中，将没有任何变量可以访问。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>mypartial<span class="token punctuation">&quot;</span></span> only <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h3 id="将标记作为变量传递"><a href="#将标记作为变量传递" class="header-anchor">#</a> 将标记作为变量传递</h3><p>可以通过向部件标签添加 <code>body</code> 属性来将标记传递给部件。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>card<span class="token punctuation">&quot;</span></span> body <span class="token delimiter punctuation">%}</span></span>
    This is the card contents
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endpartial</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>内容在部件内作为 <code>body</code> 变量可用。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> body<span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>结合<a href="./../../markup/tag/placeholder.html">占位符标记标签</a>，这可以让您构建可组合的部件。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>card<span class="token punctuation">&quot;</span></span> image<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>img.jpg<span class="token punctuation">&quot;</span></span> body <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">put</span> header <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h2</span><span class="token punctuation">&gt;</span></span>This is the card header<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h2</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endput</span> <span class="token delimiter punctuation">%}</span></span>
    This is the card contents
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endpartial</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p><strong>card</strong> 部件由两个内容区域和一个图片变量组成。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>header<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>image<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> image <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">placeholder</span> header <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>body<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> body<span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="动态部件"><a href="#动态部件" class="header-anchor">#</a> 动态部件</h2><p>部件与页面一样，可以使用任何 Twig 功能。有关详细信息，请参阅文档的<a href="./pages.html">动态页面部分</a>。</p><h3 id="部件执行生命周期"><a href="#部件执行生命周期" class="header-anchor">#</a> 部件执行生命周期</h3><p>在部件的 PHP 代码部分中可以定义特殊函数：<code>onStart</code> 和 <code>onEnd</code>。<code>onStart</code> 函数在部件渲染之前和部件<a href="./components.html">组件</a>执行之前执行。<code>onEnd</code> 函数在部件渲染之前和部件组件执行之后执行。在 <code>onStart</code> 和 <code>onEnd</code> 函数中，您可以向 Twig 环境注入变量。使用带数组表示法的 <code>$this</code> 将变量传递给页面。</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code></code></pre></div><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?</span>
<span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;hello&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string double-quoted-string">&quot;Hello world!&quot;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token delimiter important">?&gt;</span></span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h3</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> hello <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h3</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>从外部分配给部件的变量可以在 PHP 中使用 <code>$this</code> 对象访问。</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code></code></pre></div><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?</span>
<span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;location&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">city</span> <span class="token operator">.</span> <span class="token string single-quoted-string">&#39;, &#39;</span> <span class="token operator">.</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">country</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token delimiter important">?&gt;</span></span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> location <span class="token delimiter punctuation">}}</span></span> is the same as <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> city <span class="token delimiter punctuation">}}</span></span>, <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> country <span class="token delimiter punctuation">}}</span></span>.<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>October CMS 提供的模板语言在<a href="./../../markup/templating.html">标记指南</a>中进行了描述。处理程序执行的整体顺序在文档的<a href="./layouts.html">动态布局部分</a>中进行了描述。</p><h3 id="在部件中调用-ajax-处理程序"><a href="#在部件中调用-ajax-处理程序" class="header-anchor">#</a> 在部件中调用 AJAX 处理程序</h3><p>由于部件是在页面渲染期间延迟实例化的，因此常规部件的生命周期有一些限制。为了克服这个问题，您可以使用 <code>{% ajaxPartial %}</code> 来允许在部件内部调用 AJAX 处理程序。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">ajaxPartial</span> <span class="token string"><span class="token punctuation">&quot;</span>contact-form<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><div class="custom-block tip"><p>请参阅 <a href="./../../markup/tag/ajax-partial.html">AJAX 部件 Twig 标签文章</a>以了解更多关于 <code>{% ajaxPartial %}</code> 标签的信息。</p></div><p>当从 AJAX 部件中调用处理程序时，生命周期与常规 AJAX 处理程序的运行方式不同。</p><ol><li>处理程序在部件的 <code>onEnd</code> 函数之后运行。</li><li>完整的页面生命周期会运行，包括布局、页面和父部件中的逻辑。</li><li>在请求期间所有变量都可用，包括使用 Twig 设置的变量。</li><li>部件生命周期函数不支持返回任何值。</li></ol><h4 id="另请参阅"><a href="#另请参阅" class="header-anchor">#</a> 另请参阅</h4><div class="custom-block also"><ul><li><a href="./../../markup/tag/partial.html">部件 Twig 标签</a></li><li><a href="./../../markup/tag/ajax-partial.html">AJAX 部件 Twig 标签</a></li></ul></div>`,51))])}const q=e(u,[["render",g]]);export{v as __pageData,q as default};
